package com.hellodoc.dto;
import com.hellodoc.entity.Doctor; import java.util.*;
public record DoctorPublicDto(UUID id,String firstName,String lastName,String fullName,String serviceTitle,String specialty,List<String> specialties,String city,String location,String address,String phone,String description,int durationMinutes,List<Integer> workingDays,List<MedicalServiceDto> services,java.time.Instant nextAvailability) { public static DoctorPublicDto from(Doctor d,List<Integer> days,List<MedicalServiceDto> services,java.time.Instant nextAvailability){var u=d.getUser();var names=d.getSpecialties().stream().map(s->s.getName()).sorted().toList();return new DoctorPublicDto(d.getId(),u.getFirstName(),u.getLastName(),u.getFirstName()+" "+u.getLastName(),d.getServiceTitle(),names.isEmpty()?null:names.get(0),names,d.getCity(),d.getLocation(),d.getAddress(),u.getPhone(),d.getDescription(),d.getDurationMinutes(),days,services,nextAvailability);} }
